// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    TinyERC20 token;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        token = new TinyERC20();
    }

    // IERC1271 fallback so SignatureChecker accepts orders made by this test contract
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }

    function testFuzz_property(uint256 nonce, address newOwner) public {
        vm.assume(newOwner != address(0));

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(this),
            isCall: false,
            isLong: true,
            baseAsset: address(token),
            strike: 0,
            premium: 0,
            duration: 1 days,
            expiration: block.timestamp + 1 days,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory sig = new bytes(0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        uint256 positionId = c.fillOrder(order, sig, floorAssetTokenIds);
        // positionId is the short position minted to the caller (msg.sender == address(this))
        require(c.ownerOf(positionId) == address(this), "setup");

        vm.prank(address(this));
        c.transferFrom(address(this), newOwner, positionId);

        // GENERAL RULE: after an authorized transferFrom, ownerOf(id) == recipient.
        assertTrue(c.ownerOf(positionId) == newOwner);
    }
}

contract TinyERC20 {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }
    function approve(address, uint256) external pure returns (bool) {
        return true;
    }
}
